            ('m', 'any', 'Default: 1', '1'),
            ('k', 'any', 'Default: []'),
            ('lbnd', 'any', 'Default: 0', '0'),
            ('scl', 'any', 'Default: 1', '1'),
            ('axis', 'any', 'Default: 0', '0'),
