            ('ftol', 'any', 'Default: 0.0001', '0.0001'),
            ('maxiter', 'any', 'Default: None', 'None'),
            ('maxfun', 'any', 'Default: None', 'None'),
            ('full_output', 'any', 'Default: 0', '0'),
