            ('kernel_size', 'int', 'Default: 5', '5'),
            ('n_freq', 'int', 'Default: 128', '128'),
            ('n_hidden', 'int', 'Default: 128', '128'),
            ('n_output', 'int', 'Default: 128', '128'),
