            ('cooldown', 'int', 'Default: 0', '0'),
            ('warmup', 'int', 'Default: 0', '0'),
            ('min_lr', 'vector', 'Default: 0.001', '0.001'),
            ('max_lr', 'vector', 'Default: 1.0', '1.0'),
            ('eps', 'float', 'Default: 1e-08', '1e-08'),
            ('verbose', 'bool', 'Default: False', 'False'),
            ('smooth', 'bool', 'Default: False', 'False'),
            ('window_size', 'int', 'Default: 50', '50'),
            ('reset_start', 'int', 'Default: 500', '500'),
